import{TERRAIN_TYPES}from'./terrain-types.js?v=map-chat-1';
import{WORLD,worldRect,inWorld}from'./world.js?v=expanded-grid-1';
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export const order=people=>[...people].sort((a,b)=>(a.turnPosition??1000)-(b.turnPosition??1000));
// Retain the displayed order of old saves once; later additions always append.
export function prepareManualOrder(state){
 const sorted=state.manualOrder?order(state.people):[...state.people].sort((a,b)=>{
  const rank=(a.turnPosition??1000)-(b.turnPosition??1000);return rank||((b.init??0)-(a.init??0));
 });
 sorted.forEach((p,i)=>p.turnPosition=i);state.manualOrder=true;
}

export function reorderCombatants(people,sourceId,targetId,after=false){const sorted=order(people),from=sorted.findIndex(p=>p.id===sourceId);if(from<0||sourceId===targetId||!sorted.some(p=>p.id===targetId))return false;const [moved]=sorted.splice(from,1),to=sorted.findIndex(p=>p.id===targetId)+(after?1:0);sorted.splice(to,0,moved);sorted.forEach((p,i)=>p.turnPosition=i);return true;}
export function resetCombatantOrder(people){for(const p of people)delete p.turnPosition;}
export function advance(state){const list=order(state.people);if(!list.length)return;let i=list.findIndex(p=>p.id===state.active);if(i<0){state.active=list[0].id;return;}i++;if(i===list.length){i=0;state.round++;}state.active=list[i].id;}
export function simplify(points,epsilon=5){if(points.length<3)return points;const a=points[0],b=points.at(-1),dx=b.x-a.x,dy=b.y-a.y,l=dx*dx+dy*dy;let max=0,index=0;for(let i=1;i<points.length-1;i++){let t=l?clamp(((points[i].x-a.x)*dx+(points[i].y-a.y)*dy)/l,0,1):0;let d=Math.hypot(points[i].x-a.x-t*dx,points[i].y-a.y-t*dy);if(d>max){max=d;index=i;}}if(max<=epsilon)return[a,b];return[...simplify(points.slice(0,index+1),epsilon).slice(0,-1),...simplify(points.slice(index),epsilon)];}
export function recognize(points,snap=true){if(points.length<2)return null;let minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y));let w=maxX-minX,h=maxY-minY,diag=Math.hypot(w,h);if(diag<12)return null;const round=n=>snap?Math.round(n/50)*50:Math.round(n);const first=points[0],last=points.at(-1);if(Math.hypot(first.x-last.x,first.y-last.y)<Math.max(25,diag*.22)&&w>35&&h>35){const edgeDistance=points.reduce((s,p)=>s+Math.min(Math.abs(p.x-minX),Math.abs(p.x-maxX),Math.abs(p.y-minY),Math.abs(p.y-maxY)),0)/points.length;return{type:edgeDistance<Math.min(w,h)*.04?'rect':'ellipse',x:round(minX),y:round(minY),w:Math.max(50,round(maxX)-round(minX)),h:Math.max(50,round(maxY)-round(minY))};}let reduced=simplify(points,Math.max(7,diag*.035));if(reduced.length<=3){return{type:'wall',points:[{x:round(first.x),y:round(first.y)},{x:round(last.x),y:round(last.y)}]};}const output=reduced.map(p=>({x:round(p.x),y:round(p.y)})).filter((p,i,a)=>!i||p.x!==a[i-1].x||p.y!==a[i-1].y);return{type:'path',points:output};}
export function validState(s){if(!s||s.version!==1||typeof s.title!=='string'||s.title.length>80||!Array.isArray(s.people)||s.people.length>100||!Array.isArray(s.shapes)||s.shapes.length>1000||!Number.isInteger(s.round)||s.round<1||s.round>100000)return false;if(s.initiativeEnabled!==undefined&&typeof s.initiativeEnabled!=='boolean')return false;const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b;const point=inWorld;let ids=new Set();for(const p of s.people){if(!p||typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||p.name.length>50||!['ally','enemy'].includes(p.kind)||!num(p.max,1,9999)||!num(p.hp,0,p.max)||!num(p.init,-99,999)||!point(p))return false;if(p.initiativeSet===true&&!Number.isInteger(p.init))return false;if(p.initiativeSet!==undefined&&typeof p.initiativeSet!=='boolean')return false;if(p.mapHidden!==undefined&&typeof p.mapHidden!=='boolean')return false;if(p.turnPosition!==undefined&&(!Number.isInteger(p.turnPosition)||p.turnPosition<0||p.turnPosition>99))return false;ids.add(p.id);}if(s.active!==null&&!ids.has(s.active))return false;for(const sh of s.shapes){if(!sh||typeof sh.id!=='string')return false;if(sh.sketch!==undefined&&typeof sh.sketch!=='boolean')return false;if(sh.terrain!==undefined&&(typeof sh.terrain!=='string'||!Object.hasOwn(TERRAIN_TYPES,sh.terrain)||!TERRAIN_TYPES[sh.terrain].includes(sh.type)))return false;if(sh.type==='door'){if(!Array.isArray(sh.points)||sh.points.length!==2||!sh.points.every(point)||typeof sh.open!=='boolean'||Math.hypot(sh.points[0].x-sh.points[1].x,sh.points[0].y-sh.points[1].y)<1)return false;}else if(['wall','path'].includes(sh.type)){if(!Array.isArray(sh.points)||sh.points.length<2||sh.points.length>2000||!sh.points.every(point))return false;}else if(sh.type==='room'){if(!Array.isArray(sh.rings)||!sh.rings.length||sh.rings.length>100||sh.rings.reduce((n,r)=>n+(Array.isArray(r)?r.length:2001),0)>2000||!sh.rings.every(r=>Array.isArray(r)&&r.length>=3&&r.every(point)))return false;}else if(['rect','ellipse'].includes(sh.type)){if(!point(sh)||!num(sh.w,1,worldRect.width)||!num(sh.h,1,worldRect.height)||sh.x+sh.w>WORLD.right||sh.y+sh.h>WORLD.bottom)return false;}else return false;}return true;}
